'use strict';

// MODULES //

var DataView = require( '@stdlib/array/dataview' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var cases = require( './fixtures/reference.json' ).cases;
var view = new DataView( new ArrayBuffer(8) );


// FUNCTIONS //

/**
* Decodes one immutable IEEE binary64 reference value.
* @private
* @param {string} value - reference bits
* @returns {number} reference value
*/
function decode( value ) {
	view.setUint32( 0, parseInt(value.slice(0, 8), 16) );
	view.setUint32( 4, parseInt(value.slice(8), 16) );
	return view.getFloat64( 0 );
}
/**
* Encodes exact finite/signed-zero bits, or a bounded NaN class.
* @private
* @param {number} value - observed value
* @returns {string} bits or NaN class
*/
function bits( value ) {
	var hi;
	var lo;
	if ( (value !== value) ) {
		return 'NaN';
	}
	view.setFloat64( 0, value );
	hi = (('00000000'+view.getUint32(0).toString(16))).slice(-8);
	lo = (('00000000'+view.getUint32(4).toString(16))).slice(-8);
	return (hi+lo);
}
/**
* Maps a dense factor cell independently of rank-update traversal.
* @private
* @param {Object} x - immutable fixture
* @param {Float64Array} a - band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @param {NonNegativeInteger} i - dense row
* @param {NonNegativeInteger} j - dense column
* @returns {number} dense factor cell
*/
function cell( x, a, r, c, o, i, j ) {
	if ( (x.uplo === 'U') ) {
		return ( ((i <= j) && ((j-i) <= x.kd)) ) ? a[((o+((((x.kd+i)-j))*r))+(j*c))] : 0;
	}
	return ( ((i >= j) && ((i-j) <= x.kd)) ) ? a[((o+(((i-j))*r))+(j*c))] : 0;
}
/**
* Checks the completed finite prefix using original dense band equations.
* @private
* @param {Object} x - immutable fixture
* @param {Float64Array} a - band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @returns {NonNegativeNumber} normalized residual
*/
function equations( x, a, r, c, o ) {
	var prefix;
	var error;
	var scale;
	var value;
	var pivot;
	var right;
	var dense;
	var left;
	var i;
	var j;
	var k;
	dense = x.dense_input_bits.map( decode );
	prefix = ( (x.INFO === 0) ) ? x.n : (x.INFO-1);
	error = 0;
	scale = 1;
	for ( i = 0; (i < dense.length); i += 1 ) {
		scale = max( scale, abs(dense[i]) );
	}
	for ( i = 0; (i < x.n); i += 1 ) {
		for ( j = 0; (j < x.n); j += 1 ) {
			if ( (min(i, j) < prefix) ) {
				value = 0;
				for ( k = 0; (k <= min(i, j)); k += 1 ) {
					left = ( (x.uplo === 'U') ) ? cell(x, a, r, c, o, k, i) : cell(x, a, r, c, o, i, k);
					right = ( (x.uplo === 'U') ) ? cell(x, a, r, c, o, k, j) : cell(x, a, r, c, o, j, k);
					value += (left*right);
				}
				error = max( error, (abs((value-dense[((i*x.n)+j)]))/scale) );
			}
		}
	}
	if ( (x.INFO !== 0) ) {
		pivot = dense[((prefix*x.n)+prefix)];
		for ( k = 0; (k < prefix); k += 1 ) {
			value = ( (x.uplo === 'U') ) ? cell(x, a, r, c, o, k, prefix) : cell(x, a, r, c, o, prefix, k);
			pivot -= (value*value);
		}
		error = max( error, (max(pivot, 0)/scale) );
	}
	return error;
}
/**
* Executes all immutable fixtures with padding, signed views and equations.
* @private
* @param {Object} t - assertion context
* @param {Function} routine - public routine
* @returns {NonNegativeInteger} executed factor calls
*/
function run( t, routine ) {
	var total = 0;
	cases.forEach( function eachCase( x ) {
		[ true, false ].forEach( function eachLayout( column ) {
			[ [1, 1], [1, -1], [-1, 1], [-1, -1] ].forEach( function eachDirection( signs ) {
				one( x, column, signs[0], signs[1], false );
			});
			one( x, column, 1, 1, true );
		});
	});
	t.comment( (('Executed '+total)+' factor calls, including source-derived masks and finite prefix equations.') );
	return total;

	/**
* Runs a full logical fixture through one actual public entry.
* @private
* @param {Object} x - immutable fixture
* @param {boolean} column - column-major storage
* @param {integer} signR - row direction
* @param {integer} signC - column direction
* @param {boolean} main - main entry
* @returns {void}
*/
	function one( x, column, signR, signC, main ) {
		var unchanged;
		var expected;
		var allowed;
		var output;
		var before;
		var offset;
		var input;
		var lower;
		var upper;
		var index;
		var info;
		var raw;
		var row;
		var col;
		var r;
		var c;
		var h;
		var a;
		var i;
		var q;
		h = (x.kd+1);
		r = ((( column ) ? 1 : (x.n+2))*signR);
		c = ((( column ) ? (h+2) : 1)*signC);
		lower = (min( (((h-1))*r), 0 )+min( (((x.n-1))*c), 0 ));
		upper = (max( (((h-1))*r), 0 )+max( (((x.n-1))*c), 0 ));
		offset = ( main ) ? 0 : (4-lower);
		a = new Float64Array( ( x.n ) ? ((upper-lower)+(( main ) ? 5 : 9)) : 9 );
		for ( i = 0; (i < a.length); i += 1 ) {
			a[i] = (123456.25+i);
		}
		input = x.input_bits.map( decode );
		for ( q = 0; (q < input.length); q += 1 ) {
			row = (q%h);
			col = (((q-row))/h);
			a[((offset+(row*r))+(col*c))] = ( (x.selected_logical_indices.indexOf(q) < 0) ) ? NaN : input[q];
		}
		raw = new Uint8Array( a.buffer );
		before = Array.prototype.slice.call( raw );
		info = ( main ) ? routine(( column ) ? 'column-major' : 'row-major', ( (x.uplo === 'U') ) ? 'upper' : 'lower', x.n, x.kd, a, ( column ) ? (h+2) : (x.n+2)) : routine.ndarray(( (x.uplo === 'U') ) ? 'upper' : 'lower', x.n, x.kd, a, r, c, offset);
		total += 1;
		expected = x.output_bits.map( function want( b, z ) {
			return ( (x.selected_logical_indices.indexOf(z) < 0) ) ? 'NaN' : bits(decode(b));
		} );
		output = [];
		allowed = {};
		for ( q = 0; (q < input.length); q += 1 ) {
			row = (q%h);
			col = (((q-row))/h);
			index = ((offset+(row*r))+(col*c));
			output.push( bits(a[index]) );
			if ( (x.write_logical_indices.indexOf(q) >= 0) ) {
				allowed[index] = true;
			}
		}
		unchanged = true;
		for ( i = 0; (i < raw.length); i += 1 ) {
			if ( (!allowed[(((i-(i%8)))/8)] && (raw[i] !== before[i])) ) {
				unchanged = false;
			}
		}
		t.strictEqual( info, x.INFO, (((x.name+' ')+x.uplo)+' source INFO') );
		t.deepEqual( output, expected, 'exact finite/signed-zero/reference exceptional class' );
		t.ok( unchanged, 'whole guards, stars, padding and failed-prefix mask unchanged' );
		if ( (x.domain === 'finite') ) {
			t.ok( (equations(x, a, r, c, offset) < 2e-14), 'independent dense finite band/prefix equation' );
		}
	}
}


// EXPORTS //

run.bits = bits;
run.decode = decode;
module.exports = run;
